class VatanApp extends StatefulWidget {
  const VatanApp({super.key});
  @override State<VatanApp> createState() => _VatanAppState();
}
class _VatanAppState extends State<VatanApp> {
  final api = VatanApi();
  String? token;
  Map<String,dynamic>? user;
  String language = 'fa';
  bool light = false, loading = true;
  @override void initState() { super.initState(); _restore(); }
  Future<void> _restore() async {
    final prefs = await SharedPreferences.getInstance();
    final saved = await _secure.read(key:'vatan_token');
    try {
      if (saved != null) { final me = await api.me(saved); token=saved; user=Map<String,dynamic>.from(me['user'] is Map ? me['user'] : me); }
    } catch (_) { await _secure.delete(key:'vatan_token'); }
    if (!mounted) return;
    setState(() { language=prefs.getString('language')??'fa'; light=prefs.getBool('light')??false; loading=false; });
  }
  Future<void> authenticate(Map<String,dynamic> result) async {
    final nextToken = result['token']?.toString();
    if (nextToken == null || nextToken.isEmpty) throw VatanApiException('سرور توکن ورود برنگرداند.');
    await _secure.write(key:'vatan_token',value:nextToken);
    if (!mounted) return;
    setState(() { token=nextToken; user=Map<String,dynamic>.from(result['user'] is Map ? result['user'] : {}); });
  }
  Future<void> signOut() async {
    final old=token;
    await _secure.delete(key:'vatan_token');
    if (old!=null) { try { await api.logout(old); } catch (_) {} }
    if (mounted) setState(() { token=null; user=null; });
  }
  Future<void> setLight(bool value) async { final p=await SharedPreferences.getInstance(); await p.setBool('light',value); if(mounted)setState(()=>light=value); }
  Future<void> setLanguage(String value) async { final p=await SharedPreferences.getInstance(); await p.setString('language',value); if(mounted)setState(()=>language=value); }
  @override Widget build(BuildContext context) {
    final base=ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:vBlue,brightness:light?Brightness.light:Brightness.dark),inputDecorationTheme:InputDecorationTheme(filled:true,fillColor:light?Colors.white:const Color(0xFF12243A),border:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none),enabledBorder:OutlineInputBorder(borderRadius:BorderRadius.circular(16),borderSide:BorderSide.none),contentPadding:const EdgeInsets.symmetric(horizontal:16,vertical:14)));
    return MaterialApp(debugShowCheckedModeBanner:false,title:'Vatan',locale:Locale(language),supportedLocales:const[Locale('fa'),Locale('en'),Locale('ar')],localizationsDelegates:const[GlobalMaterialLocalizations.delegate,GlobalWidgetsLocalizations.delegate,GlobalCupertinoLocalizations.delegate],theme:base.copyWith(scaffoldBackgroundColor:const Color(0xFFF3F6FC),textTheme:GoogleFonts.vazirmatnTextTheme(base.textTheme)),darkTheme:base.copyWith(scaffoldBackgroundColor:vInk,textTheme:GoogleFonts.vazirmatnTextTheme(base.textTheme)),themeMode:light?ThemeMode.light:ThemeMode.dark,home:loading?const Splash():token==null?AuthPage(api:api,language:language,onAuthenticated:authenticate):MessengerHome(api:api,token:token!,user:user??{},language:language,light:light,onLight:setLight,onLanguage:setLanguage,onLogout:signOut,onUser:(u)=>setState(()=>user=u)));
  }
}
